package net.officefloor.hq.app.person;

/** A person's fields, the signed-in user (`by`) making the change, — for an edit — the version
 *  of the person the form loaded (null on an add), and the date the grade is given from (blank or null: the sheet's
 *  today; an add's grade applies from the beginning of time), and the person's own terms (blank or null: none; validated,
 *  a whole number of days). */
public record PersonRequest(String name, String grade, String by, Long version, String gradeFrom, String terms) {

    /** The terms as a number of days; null when blank. */
    public Integer termsDays() {
        return terms == null || terms.isEmpty() ? null : Integer.valueOf(terms);
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import java.util.Set;
import java.util.regex.Pattern;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** A person's fields: a name (required), a grade, one of A, B or C, and the grade's from-date (blank, or a date as
 *  YYYY-MM-DD) and their own terms (blank for none, or a whole number of days). Publishes them trimmed, with the user making the change. */
public class ValidatePerson {

    private static final Set<String> GRADES = Set.of("A", "B", "C");
    private static final Pattern DAYS = Pattern.compile("\\d{1,5}");

    public void validate(@RequestBody PersonRequest request, Out<PersonRequest> person,
            Out<ChangedBy> changedBy) throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String name = PersonName.of(request == null ? null : request.name());
        String grade = request == null || request.grade() == null ? "" : request.grade().trim();
        if (!GRADES.contains(grade)) {
            throw new BadRequestException("Choose a grade: A, B or C");
        }
        String gradeFrom = request.gradeFrom() == null ? "" : request.gradeFrom().trim();
        if (!gradeFrom.isEmpty()) {
            try {
                LocalDate.parse(gradeFrom);
            } catch (DateTimeParseException e) {
                throw new BadRequestException("Enter the grade's from-date as YYYY-MM-DD");
            }
        }
        String terms = request.terms() == null ? "" : request.terms().trim();
        if (!terms.isEmpty() && !DAYS.matcher(terms).matches()) {
            throw new BadRequestException("Terms are a whole number of days, or blank for none");
        }
        person.set(new PersonRequest(name, grade, by.name(), request.version(), gradeFrom,
                terms.isEmpty() ? "" : String.valueOf(Integer.parseInt(terms))));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

public class BuildPerson {
    public void build(@Val SheetResponse sheet, @Val PersonRequest request, PersonRepository repository,
            Out<Person> person) {
        person.set(repository.insert(sheet.id(), request.name(), request.grade(), request.termsDays()));
    }
}
package net.officefloor.hq.app.person;

import java.time.LocalDate;
import java.util.Objects;
import net.officefloor.hq.app.ConflictException;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Saves the edit, refusing it (nothing written) when the person was saved by someone else since
 *  the form loaded it. The grade is given from the request's from-date (the sheet's today when blank), keeping the
 *  grades already given; the person then shows the grade in force on the sheet's today. Their own terms are replaced
 *  by the request's, publishing whether they changed. */
public class ApplyPerson {
    public void apply(@Val PersonRequest request, @Val Person person, PersonRepository repository,
            SheetRepository sheets, Out<TermsEdit> termsEdit) throws ConflictException {
        if (request.version() == null || request.version() != person.getVersion()) {
            throw new ConflictException(PersonRepository.CHANGED);
        }
        Integer before = person.getTerms();
        person.setName(request.name());
        person.setTerms(request.termsDays());
        termsEdit.set(new TermsEdit(!Objects.equals(before, person.getTerms())));
        if (!repository.update(person)) {
            throw new ConflictException(PersonRepository.CHANGED);
        }
        LocalDate today = sheets.today(person.getSheetId());
        LocalDate from = request.gradeFrom() == null || request.gradeFrom().isEmpty() ? today
                : LocalDate.parse(request.gradeFrom());
        repository.giveGrade(person, request.grade(), from, today);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPersonAdded {
    public void record(@Val Person person, @Val ChangedBy by, Audit audit) {
        audit.record("PERSON_ADDED sheet=" + person.getSheetId() + " by=" + by.name() + " name=" + person.getName()
                + " grade=" + person.getGrade() + (person.getTerms() == null ? "" : " terms=" + person.getTerms()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPersonEdited {
    public void record(@Val Person person, @Val ChangedBy by, @Val TermsEdit termsEdit, Audit audit) {
        audit.record("PERSON_EDITED sheet=" + person.getSheetId() + " by=" + by.name() + " name=" + person.getName()
                + " grade=" + person.getGrade()
                + (termsEdit.changed() ? " terms=" + (person.getTerms() == null ? "" : person.getTerms()) : ""));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/** Refuses adding a person whose name is already in use on the sheet. */
public class CheckPersonName {
    public void check(@Val SheetResponse sheet, @Val PersonRequest request, PersonRepository repository)
            throws BadRequestException {
        if (repository.nameTaken(sheet.id(), request.name(), null)) {
            throw new BadRequestException(PersonRepository.NAME_TAKEN);
        }
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;

/** Refuses renaming a person to a name another person on the sheet already has. */
public class CheckPersonRename {
    public void check(@Val SheetResponse sheet, @Val PersonRequest request, @Val Person person,
            PersonRepository repository) throws BadRequestException {
        if (repository.nameTaken(sheet.id(), request.name(), person.getId())) {
            throw new BadRequestException(PersonRepository.NAME_TAKEN);
        }
    }
}
